function firstPlayerWins(n: number): boolean {
  const win = new Array(n + 1).fill(false);
  for (let m = 2; m <= n; m++) {
    for (let x = 1; x * x <= m && !win[m]; x++) {
      if (m % x !== 0) continue;
      // both x and m / x are divisors; each must be smaller than m
      if (!win[m - x]) win[m] = true;
      const y = m / x;
      if (y < m && !win[m - y]) win[m] = true;
    }
  }
  return win[n];
}

