class Solution:
    def firstPlayerWins(self, n: int) -> bool:
        win = [False] * (n + 1)
        for m in range(2, n + 1):
            x = 1
            while x * x <= m and not win[m]:
                if m % x == 0:
                    y = m // x
                    if not win[m - x] or (y < m and not win[m - y]):
                        win[m] = True
                x += 1
        return win[n]

